let t=0,raf=[];global.performance={now:()=>t};global.requestAnimationFrame=f=>raf.push(f);
eval(s);
const run=n=>{for(let i=0;i<n;i++){t+=16.7;const f=raf.shift();f(t)}};
console.log('play label:',els.playBtn.textContent,'count:',els.count.textContent);
run(30);els.playBtn.h.click();console.log('after play:',els.playBtn.textContent);run(300);
els.speed.value='3.0';els.speed.h.input();run(100);els.canvas.h.click({clientX:100,clientY:100});
els.stepBtn.h.click();console.log('count',els.count.textContent,'fps',els.fps.textContent,'speed',els.speedHud.textContent,'btn',els.playBtn.textContent);
els.resetBtn.h.click();console.log('after reset',els.count.textContent);
EOF
node /tmp/smoke.js index.html

